6	public static class DatabaseInitializer
7	{
8	    public static async Task InitializeAsync(CueDbContext dbContext, CancellationToken cancellationToken = default)
9	    {
10	        await TryCreateExtensionAsync(dbContext, "postgis", cancellationToken);
11	        await TryCreateExtensionAsync(dbContext, "pgcrypto", cancellationToken);
12	        await dbContext.Database.EnsureCreatedAsync(cancellationToken);
13	        // EnsureCreatedAsync does not alter an existing database; new tables added
14	        // to the model must be created explicitly until EF migrations land (F-14-07).
15	        await EnsureNewTablesAsync(dbContext, cancellationToken);
16	    }
17	
18	    private static async Task EnsureNewTablesAsync(CueDbContext dbContext, CancellationToken cancellationToken)
19	    {
20	        // DDL for tables added after the databases were first created, since
21	        // EnsureCreatedAsync never alters an existing database.
22	        var statements = new[]
23	        {
24	            """
25	            CREATE TABLE IF NOT EXISTS auth.refresh_tokens (
26	                id uuid NOT NULL PRIMARY KEY,
27	                user_id uuid NOT NULL,
28	                token_hash character varying(128) NOT NULL,
29	                expires_at timestamp with time zone NOT NULL,
30	                revoked_at timestamp with time zone NULL,
31	                created_at timestamp with time zone NOT NULL
32	            );
33	            """,
34	            "CREATE UNIQUE INDEX IF NOT EXISTS ix_refresh_tokens_token_hash ON auth.refresh_tokens (token_hash);",
35	            "CREATE INDEX IF NOT EXISTS ix_refresh_tokens_user_id ON auth.refresh_tokens (user_id);",
36	            """
37	            CREATE TABLE IF NOT EXISTS auth.password_reset_tokens (
38	                id uuid NOT NULL PRIMARY KEY,
39	                user_id uuid NOT NULL,
40	                token_hash character varying(128) NOT NULL,
41	                expires_at timestamp with time zone NOT NULL,
42	                used_at timestamp with time zone NULL,
43	                created_at timestamp with time zone NOT NULL
44	            );
45	            """,
46	            "CREATE UNIQUE INDEX IF NOT EXISTS ix_password_reset_tokens_token_hash ON auth.password_reset_tokens (token_hash);",
47	            "CREATE INDEX IF NOT EXISTS ix_password_reset_tokens_user_id ON auth.password_reset_tokens (user_id);",
48	            """
49	            CREATE TABLE IF NOT EXISTS auth.email_verification_tokens (
50	                id uuid NOT NULL PRIMARY KEY,
51	                user_id uuid NOT NULL,
52	                token_hash character varying(128) NOT NULL,
53	                expires_at timestamp with time zone NOT NULL,
54	                used_at timestamp with time zone NULL,
55	                created_at timestamp with time zone NOT NULL
56	            );
57	            """,
58	            "CREATE UNIQUE INDEX IF NOT EXISTS ix_email_verification_tokens_token_hash ON auth.email_verification_tokens (token_hash);",
59	            "CREATE INDEX IF NOT EXISTS ix_email_verification_tokens_user_id ON auth.email_verification_tokens (user_id);",
60	            "ALTER TABLE auth.users ADD COLUMN IF NOT EXISTS deleted_at timestamp with time zone NULL;",
61	            "ALTER TABLE auth.users ADD COLUMN IF NOT EXISTS photo_url text NULL;"
62	        };
63	
64	        foreach (var statement in statements)
65	        {
66	            try
67	            {
68	                await dbContext.Database.ExecuteSqlRawAsync(statement, cancellationToken);
69	            }
70	            catch (PostgresException ex) when (ex.Message.Contains("does not exist", StringComparison.OrdinalIgnoreCase))
71	            {
72	                Console.WriteLine($"Warning: skipping DDL because a schema/table does not exist: {ex.MessageText}");
73	            }
74	        }
75	    }
76	
77	    private static async Task TryCreateExtensionAsync(CueDbContext dbContext, string extensionName, CancellationToken cancellationToken)
78	    {
79	        try
80	        {
81	            await dbContext.Database.ExecuteSqlRawAsync($"CREATE EXTENSION IF NOT EXISTS {extensionName};", cancellationToken);
82	        }
83	        catch (PostgresException ex) when (
84	            ex.SqlState == PostgresErrorCodes.FeatureNotSupported ||
85	            ex.Message.Contains("is not available", StringComparison.OrdinalIgnoreCase) ||
86	            ex.Message.Contains("does not exist", StringComparison.OrdinalIgnoreCase))
87	        {
88	            Console.WriteLine($"Warning: PostgreSQL extension '{extensionName}' is not available in the current database image. Continuing without it.");
89	        }
